export class DynamicOrchestrationLayer {
  constructor(agents) {
    this.agents = agents;
    this.taskQueue = [];
  }

  addTask(task) {
    this.taskQueue.push(task);
    this.allocateTasks();
  }

  allocateTasks() {
    const prioritizedTasks = this.taskQueue.sort((a, b) => b.priority - a.priority);
    prioritizedTasks.forEach(task => {
      const availableAgent = this.agents.find(agent => agent.isAvailable());
      if (availableAgent) {
        availableAgent.assignTask(task);
        this.taskQueue = this.taskQueue.filter(t => t !== task);
      }
    });
  }
}